function fail(message) {
  console.error(`FAILED: ${message}`);
  process.exit(1);
}

function assertFingerprintExpectArgs(report, expectedTriples, context) {
  const expectedPairs = expectedTriples.map(([label, flag, fingerprint]) => ({ label, flag, fingerprint }));
  const expectedArgs = expectedPairs.flatMap((entry) => [entry.flag, entry.fingerprint]);
  const expectedArgsByFlag = Object.fromEntries(expectedPairs.map((entry) => [entry.flag, entry.fingerprint]));
  if (
    JSON.stringify(report.expectArgs) !== JSON.stringify(expectedArgs)
    || JSON.stringify(report.expectArgPairs) !== JSON.stringify(expectedPairs)
    || JSON.stringify(report.expectArgsByFlag || {}) !== JSON.stringify(expectedArgsByFlag)
  ) {
    fail(`${context}: artifact fingerprint helper should publish equivalent expectArgs, expectArgPairs, and expectArgsByFlag, got ${JSON.stringify({
      expectArgs: report.expectArgs,
      expectArgPairs: report.expectArgPairs,
      expectArgsByFlag: report.expectArgsByFlag
    })}`);
  }
}

function assertProductionAdapterSchemaVersionPropagation() {
  const hardcodedSchemaVersionPattern = /schemaVersion:\s*["']0\.1\.0["']/;
  const hardcodedSchemaNamePattern = /schema:\s*["']bobercad-reference-(?:geometry|point-cloud-chunk)["']/;
  for (const emitter of PRODUCTION_ADAPTER_SCHEMA_VERSION_EMITTERS) {
    const source = fs.readFileSync(emitter.path, "utf8");
    if (hardcodedSchemaVersionPattern.test(source)) {
      fail(`${path.relative(ROOT, emitter.path)} must emit canonical schemaVersion values from adapter request schemaVersions instead of a hardcoded literal`);
    }
    if (hardcodedSchemaNamePattern.test(source)) {
      fail(`${path.relative(ROOT, emitter.path)} must emit canonical schema names from local schema files instead of a hardcoded literal`);
    }
    for (const snippet of emitter.requiredSnippets) {
      if (!source.includes(snippet)) {
        fail(`${path.relative(ROOT, emitter.path)} is missing adapter request schema-version propagation snippet: ${snippet}`);
      }
    }
  }
}

function findFilesContaining(rootDir, patterns) {
  if (!fs.existsSync(rootDir)) return [];
  const matches = [];
  for (const entry of fs.readdirSync(rootDir, { withFileTypes: true })) {
    const entryPath = path.join(rootDir, entry.name);
    if (entry.isDirectory()) {
      matches.push(...findFilesContaining(entryPath, patterns));
    } else if (entry.isFile() && patterns.some((pattern) => entry.name.includes(pattern))) {
      matches.push(entryPath);
    }
  }
  return matches;
}

