function expectedDirectoryStatFingerprintFromParts(
  directoryName,
  directoryModifiedTime,
  directoryEntryCount,
  directoryFileCount,
  directoryDirectoryCount,
  directoryFileSizeBytes,
  directoryLatestModifiedTime
) {
  const text = [
    directoryName || "",
    directoryModifiedTime || "",
    Number.isInteger(directoryEntryCount) ? String(directoryEntryCount) : "",
    Number.isInteger(directoryFileCount) ? String(directoryFileCount) : "",
    Number.isInteger(directoryDirectoryCount) ? String(directoryDirectoryCount) : "",
    Number.isInteger(directoryFileSizeBytes) ? String(directoryFileSizeBytes) : "",
    directoryLatestModifiedTime || ""
  ].join("\0");
  return `stat-sha256:${crypto.createHash("sha256").update(text).digest("hex")}`;
}

function expectedDirectoryStatMetadata(directoryPath) {
  const stat = fs.statSync(directoryPath);
  let directoryEntryCount = 0;
  let directoryFileCount = 0;
  let directoryDirectoryCount = 0;
  let directoryFileSizeBytes = 0;
  let latestModifiedMs = stat.mtime.getTime();
  const entries = fs.readdirSync(directoryPath, { withFileTypes: true })
    .sort((a, b) => a.name.localeCompare(b.name));
  directoryEntryCount = entries.length;
  for (const entry of entries) {
    const entryStat = fs.statSync(path.join(directoryPath, entry.name));
    if (entryStat.isFile()) {
      directoryFileCount += 1;
      directoryFileSizeBytes += entryStat.size;
    } else if (entryStat.isDirectory()) {
      directoryDirectoryCount += 1;
    }
    latestModifiedMs = Math.max(latestModifiedMs, entryStat.mtime.getTime());
  }
  const directoryModifiedTime = stat.mtime.toISOString();
  const directoryLatestModifiedTime = new Date(latestModifiedMs).toISOString();
  return {
    directoryModifiedTime,
    directoryEntryCount,
    directoryFileCount,
    directoryDirectoryCount,
    directoryFileSizeBytes,
    directoryLatestModifiedTime,
    directoryStatFingerprint: expectedDirectoryStatFingerprintFromParts(
      path.basename(directoryPath),
      directoryModifiedTime,
      directoryEntryCount,
      directoryFileCount,
      directoryDirectoryCount,
      directoryFileSizeBytes,
      directoryLatestModifiedTime
    )
  };
}

