function assertReferenceTranslationWorkflowStatus(summary, stage, context, { stageComplete = true } = {}) {
  const status = summary?.referenceTranslationWorkflowStatus;
  if (!status || typeof status !== "object" || Array.isArray(status)) {
    fail(`${context}: referenceTranslationWorkflowStatus should be an object`);
  }
  const expectedDecisionField = {
    "source-discovery": "referenceTranslationSourceDecision",
    "plan-only": "referenceTranslationPlanDecision",
    "adapter-request": "referenceTranslationAdapterRequestDecision",
    "external-adapter-wrapper": "referenceTranslationAdapterRequestDecision",
    translate: null,
    "validate-only": null
  }[stage];
  const defaultExpectedNext = {
    "source-discovery": ["plan-only"],
    "plan-only": ["adapter-request", "translate"],
    "adapter-request": ["external-adapter-wrapper", "validate-only"],
    "external-adapter-wrapper": ["validate-only"],
    translate: ["validate-only"],
    "validate-only": []
  }[stage];
  const expectedNext = stage === "plan-only" && Array.isArray(summary.referenceTranslationPlanDecision?.availableNextExecutionModes)
    ? summary.referenceTranslationPlanDecision.availableNextExecutionModes
    : defaultExpectedNext;
  if (
    status.workflowStage !== stage
    || status.workflowStageComplete !== stageComplete
    || !Array.isArray(status.completedWorkflowStages)
    || (stageComplete && !status.completedWorkflowStages.includes(stage))
    || (!stageComplete && status.completedWorkflowStages.includes(stage))
    || !Array.isArray(status.nextWorkflowStages)
    || JSON.stringify(status.nextWorkflowStages) !== JSON.stringify(expectedNext)
    || status.workflowDecisionField !== expectedDecisionField
    || !Array.isArray(status.workflowFingerprintFields)
    || typeof status.noProjectWrites !== "boolean"
    || typeof status.noTargetReferenceWrites !== "boolean"
    || typeof status.promotedReferenceWriteStage !== "boolean"
    || typeof status.writesTargetReferenceManifest !== "boolean"
    || typeof status.mayLaunchExternalAdapter !== "boolean"
    || !status.sideEffectBoundary
    || typeof status.sideEffectBoundary !== "object"
    || Array.isArray(status.sideEffectBoundary)
  ) {
    fail(`${context}: referenceTranslationWorkflowStatus should expose current stage, completion state, completed/next stages, decision field, fingerprint fields, and side-effect boundary`);
  }
  if (stage === "source-discovery") {
    if (
      status.noProjectWrites !== true
      || status.noTargetReferenceWrites !== true
      || status.sideEffectBoundary.runsTranslator !== false
      || status.writesTargetReferenceManifest !== false
    ) {
      fail(`${context}: source-discovery workflow status should be side-effect-free`);
    }
  }
  if (stage === "plan-only") {
    const expectedRecommendedStage = summary.referenceTranslationPlanDecision?.safeNextExecutionMode || "adapter-request";
    if (
      status.noProjectWrites !== true
      || status.noTargetReferenceWrites !== true
      || status.sideEffectBoundary.validatesOutputPlan !== true
      || status.recommendedNextWorkflowStage !== expectedRecommendedStage
    ) {
      fail(`${context}: plan-only workflow status should validate the output plan without target writes`);
    }
  }
  if (stage === "adapter-request") {
    if (
      status.noProjectWrites !== true
      || status.noTargetReferenceWrites !== true
      || status.sideEffectBoundary.writesAdapterRequest !== true
      || status.recommendedNextWorkflowStage !== "external-adapter-wrapper"
    ) {
      fail(`${context}: adapter-request workflow status should report request-only writes and route to the external wrapper`);
    }
  }
  if (stage === "translate") {
    if (
      status.noProjectWrites !== true
      || status.noTargetReferenceWrites !== false
      || status.promotedReferenceWriteStage !== true
      || status.writesTargetReferenceManifest !== true
    ) {
      fail(`${context}: translate workflow status should report promoted reference writes without project writes`);
    }
  }
  if (stage === "validate-only") {
    if (
      status.noProjectWrites !== true
      || status.noTargetReferenceWrites !== true
      || status.sideEffectBoundary.validatesExistingReferenceManifest !== true
      || status.nextWorkflowStages.length !== 0
    ) {
      fail(`${context}: validate-only workflow status should report read-only canonical validation`);
    }
  }
}

