function assertReferenceImportWorkflowStatus(summary, stage, context, { stageComplete = true } = {}) {
  const status = summary?.referenceImportWorkflowStatus;
  if (!status || typeof status !== "object" || Array.isArray(status)) {
    fail(`${context}: referenceImportWorkflowStatus should be an object`);
  }
  const expectedDecisionField = {
    "source-discovery": "referenceImportSourceDecision",
    "plan-only": "referenceImportPlanDecision",
    "adapter-preflight": "adapterPreflightDecision",
    "adapter-request": "referenceImportAdapterRequestDecision",
    "dry-run": "referenceImportDryRunDecision",
    import: "referenceImportPromotionDecision",
    "check-references": "referenceAuditDecision"
  }[stage];
  const sourceDecision = summary?.referenceImportSourceDecision || {};
  const expectedSourceNext = sourceDecision.sourceFileReadyForImport !== true
    ? ["source-discovery"]
    : sourceDecision.externalAdapterRequired === true
      ? ["adapter-preflight", "plan-only"]
      : ["plan-only"];
  const expectedNext = {
    "source-discovery": expectedSourceNext,
    "adapter-preflight": ["plan-only", "dry-run"],
    "adapter-request": ["dry-run"],
    "dry-run": ["import"],
    import: ["check-references"],
    "check-references": []
  }[stage] || null;
  if (
    status.workflowStage !== stage
    || status.workflowStageComplete !== stageComplete
    || !Array.isArray(status.completedWorkflowStages)
    || (stageComplete && !status.completedWorkflowStages.includes(stage))
    || (!stageComplete && status.completedWorkflowStages.includes(stage))
    || !Array.isArray(status.nextWorkflowStages)
    || (expectedNext && JSON.stringify(status.nextWorkflowStages) !== JSON.stringify(expectedNext))
    || status.workflowDecisionField !== expectedDecisionField
    || !Array.isArray(status.workflowFingerprintFields)
    || typeof status.noProjectOrTargetWrites !== "boolean"
    || typeof status.promotedWriteStage !== "boolean"
    || typeof status.writesProjectJson !== "boolean"
    || typeof status.writesTargetReferenceManifest !== "boolean"
    || typeof status.mayLaunchExternalAdapter !== "boolean"
    || !status.sideEffectBoundary
    || typeof status.sideEffectBoundary !== "object"
    || Array.isArray(status.sideEffectBoundary)
  ) {
    fail(`${context}: referenceImportWorkflowStatus should expose current stage, completion state, completed/next stages, decision field, fingerprint fields, and side-effect boundary`);
  }
  if (stage === "plan-only") {
    if (
      status.noProjectOrTargetWrites !== true
      || status.writesProjectJson !== false
      || !status.nextWorkflowStages.includes("dry-run")
      || status.recommendedNextWorkflowStage !== "dry-run"
    ) {
      fail(`${context}: plan-only workflow status should route to dry-run without project writes`);
    }
  }
  if (stage === "source-discovery") {
    const expectedRecommended = expectedSourceNext[0] || null;
    if (
      status.noProjectOrTargetWrites !== true
      || status.sideEffectBoundary.runsTranslator !== false
      || status.writesProjectJson !== false
      || status.recommendedNextWorkflowStage !== expectedRecommended
    ) {
      fail(`${context}: source-discovery workflow status should route from source readiness without project writes`);
    }
  }
  if (stage === "adapter-preflight") {
    if (
      status.noProjectOrTargetWrites !== true
      || status.sideEffectBoundary.preflightsAdapter !== true
      || status.mayLaunchExternalAdapter !== false
      || status.writesProjectJson !== false
      || JSON.stringify(status.nextWorkflowStages) !== JSON.stringify(["plan-only", "dry-run"])
    ) {
      fail(`${context}: adapter-preflight workflow status should report no-launch/no-write preflight and route to plan/dry-run`);
    }
  }
  if (stage === "adapter-request") {
    if (
      status.noProjectOrTargetWrites !== true
      || status.sideEffectBoundary.writesAdapterRequest !== true
      || JSON.stringify(status.nextWorkflowStages) !== JSON.stringify(["dry-run"])
    ) {
      fail(`${context}: adapter-request workflow status should report request-only writes and route to dry-run`);
    }
  }
  if (stage === "dry-run") {
    if (
      status.noProjectOrTargetWrites !== true
      || status.sideEffectBoundary.runsTranslator !== true
      || status.writesProjectJson !== false
      || JSON.stringify(status.nextWorkflowStages) !== JSON.stringify(["import"])
    ) {
      fail(`${context}: dry-run workflow status should report translator execution without project writes and route to import`);
    }
  }
  if (stage === "import") {
    if (
      status.promotedWriteStage !== true
      || status.writesProjectJson !== true
      || status.writesTargetReferenceManifest !== true
      || JSON.stringify(status.nextWorkflowStages) !== JSON.stringify(["check-references"])
    ) {
      fail(`${context}: import workflow status should report promoted writes and route to check-references`);
    }
  }
  if (stage === "check-references") {
    if (
      status.noProjectOrTargetWrites !== true
      || status.sideEffectBoundary.readsReferenceManifests !== true
      || status.writesProjectJson !== false
      || status.nextWorkflowStages.length !== 0
    ) {
      fail(`${context}: check-references workflow status should report read-only audit with no next import stage`);
    }
  }
}

function assertReferenceImportFailureDecision(summary, {
  failedWorkflowStage,
  failureKind,
  recommendedNextAction,
  safeNextAction = recommendedNextAction,
  likelyFixArea = failureKind,
  adapterErrorCode = null,
  workflowStageComplete = false,
  retryWorkflowStage = failedWorkflowStage
}, context) {
  const decision = summary?.referenceImportFailureDecision;
  if (!decision || typeof decision !== "object" || Array.isArray(decision)) {
    fail(`${context}: referenceImportFailureDecision should be an object`);
  }
  if (
    decision.failedWorkflowStage !== failedWorkflowStage
    || decision.workflowStageComplete !== workflowStageComplete
    || decision.adapterErrorCode !== adapterErrorCode
    || decision.failureKind !== failureKind
    || decision.likelyFixArea !== likelyFixArea
    || decision.safeNextAction !== safeNextAction
    || decision.recommendedNextAction !== recommendedNextAction
    || decision.retryWorkflowStage !== retryWorkflowStage
    || typeof decision.adapterConfigRequired !== "boolean"
    || typeof decision.adapterDependencyReviewRequired !== "boolean"
    || typeof decision.adapterRequestReviewRequired !== "boolean"
    || typeof decision.adapterRunInspectionRequired !== "boolean"
    || typeof decision.canonicalOutputFixRequired !== "boolean"
    || typeof decision.importOptionFixRequired !== "boolean"
    || typeof decision.cliOptionFixRequired !== "boolean"
  ) {
    fail(`${context}: referenceImportFailureDecision should expose failed stage, error code, fix area, next action, retry stage, and boolean fix gates`);
  }
  if (failureKind === "adapter-config" && decision.adapterConfigRequired !== true) {
    fail(`${context}: adapter-config failure should require adapter config`);
  }
  if (failureKind === "adapter-process" && decision.adapterRunInspectionRequired !== true) {
    fail(`${context}: adapter-process failure should require adapter run inspection`);
  }
  if (failureKind === "adapter-request" && decision.adapterRequestReviewRequired !== true) {
    fail(`${context}: adapter-request failure should require adapter request review`);
  }
  if (failureKind === "canonical-reference" && decision.canonicalOutputFixRequired !== true) {
    fail(`${context}: canonical-reference failure should require canonical output fix`);
  }
  if (failureKind === "import-options" && decision.importOptionFixRequired !== true) {
    fail(`${context}: import-options failure should require import option fixes`);
  }
  if (failureKind === "cli-options" && decision.cliOptionFixRequired !== true) {
    fail(`${context}: cli-options failure should require CLI option fixes`);
  }
}

