function referenceImportProducerActionTokens() {
  const producerFiles = [
    path.join(ROOT, "tools/reference-geometry/translate_reference_geometry.mjs"),
    path.join(ROOT, "tools/reference-geometry/import_reference_geometry_asset.mjs")
  ];
  const actionPrefixes = /^(add|audit|check|choose|collect|confirm|fix|import|inspect|load|plan|review|run|select|submit|use|validate|wait|write)-/;
  const nonActionTokens = new Set(["import-options", "plan-only", "validate-only"]);
  const tokens = new Set();
  for (const filePath of producerFiles) {
    const source = fs.readFileSync(filePath, "utf8");
    for (const match of source.matchAll(/"([a-z][a-z0-9]*(?:-[a-z0-9]+)+)"/g)) {
      const token = match[1];
      if (actionPrefixes.test(token) && !nonActionTokens.has(token)) {
        tokens.add(token);
      }
    }
  }
  return [...tokens].sort();
}

