function assertSummaryReferenceFileMetadata(summary, referencePath, context) {
  const stat = fs.statSync(referencePath);
  if (summary.referenceFileSizeBytes !== stat.size) {
    fail(`${context}: referenceFileSizeBytes should match manifest file stat size, got ${summary.referenceFileSizeBytes}`);
  }
  if (summary.referenceFileModifiedTime !== stat.mtime.toISOString()) {
    fail(`${context}: referenceFileModifiedTime should match manifest file stat mtime, got ${summary.referenceFileModifiedTime}`);
  }
  if (summary.referenceManifestFingerprint !== expectedReferenceManifestFingerprint(referencePath)) {
    fail(`${context}: referenceManifestFingerprint should match manifest file content, got ${summary.referenceManifestFingerprint}`);
  }
}

function expectedReferenceManifestFingerprint(referencePath) {
  return `sha256:${crypto.createHash("sha256").update(fs.readFileSync(referencePath)).digest("hex")}`;
}

function expectedReferenceChunkFileSetFingerprint(entries) {
  const normalizedEntries = entries
    .map((entry) => ({
      chunkId: entry.chunkId || null,
      path: entry.path || null,
      fileSizeBytes: Number.isInteger(entry.fileSizeBytes) ? entry.fileSizeBytes : null,
      fileModifiedTime: entry.fileModifiedTime || null
    }))
    .sort((left, right) => `${left.path || ""}\0${left.chunkId || ""}`.localeCompare(`${right.path || ""}\0${right.chunkId || ""}`));
  return `stat-sha256:${crypto.createHash("sha256").update(JSON.stringify(normalizedEntries)).digest("hex")}`;
}

function expectedReferenceArtifactFingerprint(referencePath, chunkFileSetFingerprint) {
  return `sha256:${crypto.createHash("sha256").update(JSON.stringify({
    manifest: expectedReferenceManifestFingerprint(referencePath),
    chunks: chunkFileSetFingerprint
  })).digest("hex")}`;
}

function assertSha256Fingerprint(value, context) {
  if (!/^sha256:[0-9a-f]{64}$/.test(value || "")) {
    fail(`${context}: expected sha256 fingerprint, got ${value}`);
  }
}

function assertNullTranslatedOutputFingerprints(summary, context) {
  if (summary.referenceTranslatedManifestFingerprint !== null || summary.referenceTranslatedArtifactFingerprint !== null) {
    fail(`${context}: should not report translated manifest/artifact fingerprints before translation runs`);
  }
}

function assertDryRunTranslatedOutputFingerprints(summary, context) {
  assertSha256Fingerprint(summary.referenceTranslatedManifestFingerprint, `${context} referenceTranslatedManifestFingerprint`);
  assertSha256Fingerprint(summary.referenceTranslatedArtifactFingerprint, `${context} referenceTranslatedArtifactFingerprint`);
  if (summary.referenceManifestFingerprint !== null || summary.referenceArtifactFingerprint !== null) {
    fail(`${context}: should keep promoted manifest/artifact fingerprints null when no target manifest is promoted`);
  }
}

function assertPromotedTranslatedOutputFingerprints(summary, context) {
  assertSha256Fingerprint(summary.referenceTranslatedManifestFingerprint, `${context} referenceTranslatedManifestFingerprint`);
  assertSha256Fingerprint(summary.referenceTranslatedArtifactFingerprint, `${context} referenceTranslatedArtifactFingerprint`);
  if (summary.referenceTranslatedManifestFingerprint !== summary.referenceManifestFingerprint) {
    fail(`${context}: translated manifest fingerprint should match promoted manifest fingerprint`);
  }
  if (summary.referenceTranslatedArtifactFingerprint !== summary.referenceArtifactFingerprint) {
    fail(`${context}: translated artifact fingerprint should match promoted artifact fingerprint`);
  }
}

function assertSummaryAdapterConfigFileMetadata(summary, adapterConfigPath, context) {
  const absolutePath = path.resolve(adapterConfigPath);
  const stat = fs.statSync(absolutePath);
  if (summary.adapterConfigPath !== absolutePath) {
    fail(`${context}: adapterConfigPath should be absolute config path, got ${summary.adapterConfigPath}`);
  }
  if (summary.adapterConfigFileSizeBytes !== stat.size) {
    fail(`${context}: adapterConfigFileSizeBytes should match adapter config stat size, got ${summary.adapterConfigFileSizeBytes}`);
  }
  if (summary.adapterConfigFileModifiedTime !== stat.mtime.toISOString()) {
    fail(`${context}: adapterConfigFileModifiedTime should match adapter config stat mtime, got ${summary.adapterConfigFileModifiedTime}`);
  }
  if (summary.adapterConfigStatFingerprint !== expectedAdapterConfigStatFingerprintFromParts(stat.size, stat.mtime.toISOString())) {
    fail(`${context}: adapterConfigStatFingerprint should match adapter config stat fingerprint, got ${summary.adapterConfigStatFingerprint}`);
  }
}

function assertAdapterRunId(value, context) {
  if (typeof value !== "string" || !/^[A-Za-z0-9_.:-]{8,}$/.test(value)) {
    fail(`${context}: adapterRunId should be a stable nonempty token, got ${value}`);
  }
}

function expectedAdapterRequestFingerprint(request = {}) {
  const { adapterRequestFingerprint: _fingerprint, ...payload } = request;
  return `sha256:${crypto.createHash("sha256").update(JSON.stringify(payload)).digest("hex")}`;
}

function expectedAdapterRequestEvidenceFingerprint(request = {}) {
  const payload = {
    schema: request.schema || null,
    schemaVersion: request.schemaVersion || null,
    schemaVersions: request.schemaVersions && typeof request.schemaVersions === "object" && !Array.isArray(request.schemaVersions) ? {
      adapterRequest: request.schemaVersions.adapterRequest || null,
      referenceGeometry: request.schemaVersions.referenceGeometry || null,
      pointCloudChunk: request.schemaVersions.pointCloudChunk || null
    } : null,
    format: request.format || null,
    requestedFormat: request.requestedFormat || null,
    outputMode: request.outputMode || null,
    sourceFileExtension: typeof request.sourceFileExtension === "string" ? request.sourceFileExtension : null,
    sourceFileSizeBytes: Number.isInteger(request.sourceFileSizeBytes) ? request.sourceFileSizeBytes : null,
    sourceFileModifiedTime: request.sourceFileModifiedTime || null,
    sourceStatFingerprint: request.sourceStatFingerprint || null,
    adapterKey: request.adapterKey || null,
    adapterConfigFileSizeBytes: Number.isInteger(request.adapterConfigFileSizeBytes) ? request.adapterConfigFileSizeBytes : null,
    adapterConfigFileModifiedTime: request.adapterConfigFileModifiedTime || null,
    adapterConfigStatFingerprint: request.adapterConfigStatFingerprint || null,
    adapterRegistryFingerprint: request.adapterRegistryFingerprint || null,
    adapterRegistryAdapterFingerprint: request.adapterRegistryAdapterFingerprint || null,
    assetId: request.assetId || null,
    units: request.units || null,
    pointCloudChunkSize: Number.isInteger(request.pointCloudChunkSize) ? request.pointCloudChunkSize : null,
    timeoutMs: Number.isInteger(request.timeoutMs) ? request.timeoutMs : null,
    chunkPathPrefix: request.chunkPathPrefix || null
  };
  return `sha256:${crypto.createHash("sha256").update(JSON.stringify(payload)).digest("hex")}`;
}

function assertAdapterRequestFingerprint(request, context) {
  if (!/^sha256:[0-9a-f]{64}$/.test(request?.adapterRequestFingerprint || "")) {
    fail(`${context}: adapterRequestFingerprint should be a sha256 fingerprint, got ${request?.adapterRequestFingerprint}`);
  }
  if (!/^sha256:[0-9a-f]{64}$/.test(request.adapterRequestEvidenceFingerprint || "")) {
    fail(`${context}: adapterRequestEvidenceFingerprint should be a required sha256 fingerprint, got ${request.adapterRequestEvidenceFingerprint}`);
  }
  const expectedEvidenceFingerprint = expectedAdapterRequestEvidenceFingerprint(request);
  if (request.adapterRequestEvidenceFingerprint !== expectedEvidenceFingerprint) {
    fail(`${context}: adapterRequestEvidenceFingerprint should match path-free request evidence, got ${request.adapterRequestEvidenceFingerprint}, expected ${expectedEvidenceFingerprint}`);
  }
  const expectedFingerprint = expectedAdapterRequestFingerprint(request);
  if (request.adapterRequestFingerprint !== expectedFingerprint) {
    fail(`${context}: adapterRequestFingerprint should match request payload, got ${request.adapterRequestFingerprint}, expected ${expectedFingerprint}`);
  }
}

function assertCanonicalManifestExcludesAdapterHarnessMetadata(referencePath, summary, context) {
  const raw = fs.readFileSync(referencePath, "utf8");
  if (summary?.adapterRunId && raw.includes(summary.adapterRunId)) {
    fail(`${context}: canonical reference manifest should not contain adapterRunId value`);
  }
  const data = JSON.parse(raw);
  const forbiddenKeys = new Set([
    "adapterRunId",
    "adapterCommand",
    "adapterCommandFound",
    "adapterResolvedCommand",
    "adapterCwd",
    "adapterCwdExists",
    "adapterRequestPath",
    "adapterOutputPath",
    "adapterLogPath",
    "adapterStdoutPath",
    "adapterStderrPath",
    "stageDir",
    "scratchDir",
    "adapterScratchFileCount",
    "adapterScratchFileSizeBytes",
    "adapterScratchFileModifiedTimeLatest",
    "adapterScratchFileEntries",
    "adapterScratchFileOmittedCount"
  ]);
  function visit(value, location) {
    if (Array.isArray(value)) {
      value.forEach((child, index) => visit(child, `${location}[${index}]`));
      return;
    }
    if (!value || typeof value !== "object") return;
    for (const [key, child] of Object.entries(value)) {
      if (forbiddenKeys.has(key)) {
        fail(`${context}: canonical reference manifest should not contain harness metadata key ${location}.${key}`);
      }
      visit(child, `${location}.${key}`);
    }
  }
  visit(data.asset, "asset");
  for (const [objectId, object] of Object.entries(data.objects || {})) visit(object, `objects.${objectId}`);
  for (const [index, chunk] of (data.chunks || []).entries()) visit(chunk, `chunks[${index}]`);
  for (const [index, diagnostic] of (data.diagnostics || []).entries()) visit(diagnostic, `diagnostics[${index}]`);
}

function writeInvalidAdapterBridgeRequest(requestPath, overrides = {}) {
  const requestOverrides = { ...overrides };
  const hasExplicitAdapterRequestFingerprint = Object.hasOwn(requestOverrides, "adapterRequestFingerprint");
  const hasExplicitAdapterRequestEvidenceFingerprint = Object.hasOwn(requestOverrides, "adapterRequestEvidenceFingerprint");
  const shouldWriteSourceInput = requestOverrides.__writeSourceInput !== false;
  delete requestOverrides.__writeSourceInput;
  const requestDir = path.dirname(requestPath);
  const stageDir = requestDir;
  const sourceFileExtension = typeof requestOverrides.sourceFileExtension === "string" ? requestOverrides.sourceFileExtension : "dwg";
  const sourceInput = typeof requestOverrides.input === "string"
    ? requestOverrides.input
    : path.join(requestDir, `bridge-source${sourceFileExtension ? `.${sourceFileExtension}` : ""}`);
  if (shouldWriteSourceInput) {
    fs.mkdirSync(path.dirname(path.resolve(sourceInput)), { recursive: true });
    fs.writeFileSync(sourceInput, "x", "utf8");
    fs.utimesSync(sourceInput, new Date("2026-01-01T00:00:00.000Z"), new Date("2026-01-01T00:00:00.000Z"));
  }
  const sourceStat = fs.existsSync(sourceInput) ? fs.statSync(sourceInput) : null;
  const sourceFileName = path.basename(sourceInput);
  const sourceFileModifiedTime = sourceStat ? sourceStat.mtime.toISOString() : "2026-01-01T00:00:00.000Z";
  const sourceFileSizeBytes = sourceStat ? sourceStat.size : 1;
  const outputPath = typeof requestOverrides.output === "string"
    ? requestOverrides.output
    : path.join(stageDir, "bridge-output.reference.json");
  const request = {
    $schema: path.relative(requestDir, ADAPTER_REQUEST_SCHEMA_PATH).replaceAll(path.sep, "/"),
    schema: "bobercad-reference-adapter-request",
    schemaVersion: "0.1.0",
    schemaVersions: {
      adapterRequest: "0.1.0",
      referenceGeometry: "0.1.0",
      pointCloudChunk: "0.1.0"
    },
    schemas: {
      adapterRequest: ADAPTER_REQUEST_SCHEMA_PATH,
      referenceGeometry: REFERENCE_GEOMETRY_SCHEMA_PATH,
      pointCloudChunk: POINT_CLOUD_CHUNK_SCHEMA_PATH
    },
    format: "dwg",
    requestedFormat: "dwg",
    outputMode: "file",
    input: sourceInput,
    sourceDirectory: path.dirname(path.resolve(sourceInput)),
    sourceFileName,
    sourceFileStem: path.basename(sourceInput, path.extname(sourceInput)),
    sourceFileExtension,
    output: outputPath,
    outputDir: stageDir,
    stageDir,
    request: requestPath,
    scratchDir: path.join(stageDir, "scratch"),
    chunkDir: path.join(stageDir, "chunks"),
    outputFileName: path.basename(outputPath),
    outputFileStem: path.basename(outputPath, path.extname(outputPath)),
    chunkPathPrefix: "chunks/",
    adapterLogPath: path.join(stageDir, "reference-adapter.log"),
    adapterStdoutPath: path.join(stageDir, "reference-adapter.stdout.log"),
    adapterStderrPath: path.join(stageDir, "reference-adapter.stderr.log"),
    sourceFileSizeBytes,
    sourceFileModifiedTime,
    sourceStatFingerprint: expectedSourceStatFingerprintFromParts(sourceFileExtension, sourceFileSizeBytes, sourceFileModifiedTime),
    adapterRunId: "bridge-smoke-run",
    assetId: "bridge_request_smoke",
    name: "Bridge Request Smoke",
    units: "mm",
    pointCloudChunkSize: 2,
    timeoutMs: 30000,
    ...requestOverrides
  };
  if (!hasExplicitAdapterRequestEvidenceFingerprint) {
    request.adapterRequestEvidenceFingerprint = expectedAdapterRequestEvidenceFingerprint(request);
  }
  if (!hasExplicitAdapterRequestFingerprint) {
    request.adapterRequestFingerprint = expectedAdapterRequestFingerprint(request);
  }
  fs.writeFileSync(requestPath, `${JSON.stringify(request, null, 2)}\n`, "utf8");
}

function assertBridgeAdapterRejectsRequestContract(adapterPath, requestPath, expectedPattern, context) {
  const result = spawnSync(process.execPath, [adapterPath, "--request", requestPath], {
    cwd: ROOT,
    encoding: "utf8",
    windowsHide: true
  });
  if (result.status === 0) {
    fail(`${context}: checked-in bridge adapter should reject the unsupported adapter request contract`);
  }
  const output = [result.stderr, result.stdout].filter(Boolean).join("\n");
  if (!expectedPattern.test(output)) {
    fail(`${context}: checked-in bridge adapter should reject before local converter setup, got: ${output}`);
  }
}

function assertBridgeAdapterRejectsEnvironment(adapterPath, requestPath, env, expectedPattern, context) {
  const result = spawnSync(process.execPath, [adapterPath, "--request", requestPath], {
    cwd: ROOT,
    encoding: "utf8",
    env: {
      ...process.env,
      ...env
    },
    windowsHide: true
  });
  if (result.status === 0) {
    fail(`${context}: checked-in bridge adapter should reject the unsafe adapter environment`);
  }
  const output = [result.stderr, result.stdout].filter(Boolean).join("\n");
  if (!expectedPattern.test(output)) {
    fail(`${context}: checked-in bridge adapter should reject before local converter setup, got: ${output}`);
  }
}

function assertAdapterRequestPathMetadata(error, context, { expectedStageDir = null, shouldExist = false } = {}) {
  if (!error.adapterRequestPath) {
    fail(`${context}: adapterRequestPath should be reported`);
  }
  if (path.basename(error.adapterRequestPath) !== "reference-adapter-request.json") {
    fail(`${context}: adapterRequestPath should name reference-adapter-request.json, got ${error.adapterRequestPath}`);
  }
  if (expectedStageDir) {
    const expectedPath = path.join(expectedStageDir, "reference-adapter-request.json");
    if (path.resolve(error.adapterRequestPath) !== path.resolve(expectedPath)) {
      fail(`${context}: adapterRequestPath should point at the kept stage request, got ${error.adapterRequestPath}`);
    }
  } else {
    if (!error.adapterOutputPath) {
      fail(`${context}: adapterOutputPath should be reported with adapterRequestPath`);
    }
    if (path.dirname(path.resolve(error.adapterRequestPath)) !== path.dirname(path.resolve(error.adapterOutputPath))) {
      fail(`${context}: adapterRequestPath should live beside adapterOutputPath`);
    }
  }
  if (shouldExist && !fs.existsSync(error.adapterRequestPath)) {
    fail(`${context}: adapterRequestPath should exist on disk`);
  }
}

function assertAdapterLogPathMetadata(error, context, { expectedStageDir = null, shouldExist = false } = {}) {
  if (!error.adapterLogPath) {
    fail(`${context}: adapterLogPath should be reported`);
  }
  if (path.basename(error.adapterLogPath) !== "reference-adapter.log") {
    fail(`${context}: adapterLogPath should name reference-adapter.log, got ${error.adapterLogPath}`);
  }
  if (expectedStageDir) {
    const expectedPath = path.join(expectedStageDir, "reference-adapter.log");
    if (path.resolve(error.adapterLogPath) !== path.resolve(expectedPath)) {
      fail(`${context}: adapterLogPath should point at the kept stage log, got ${error.adapterLogPath}`);
    }
  } else {
    if (!error.adapterOutputPath) {
      fail(`${context}: adapterOutputPath should be reported with adapterLogPath`);
    }
    if (path.dirname(path.resolve(error.adapterLogPath)) !== path.dirname(path.resolve(error.adapterOutputPath))) {
      fail(`${context}: adapterLogPath should live beside adapterOutputPath`);
    }
  }
  if (shouldExist && !fs.existsSync(error.adapterLogPath)) {
    fail(`${context}: adapterLogPath should exist on disk`);
  }
}

function assertAdapterStageDirMetadata(error, context, { expectedStageDir = null, shouldExist = false } = {}) {
  if (!error.stageDir) {
    fail(`${context}: stageDir should be reported`);
  }
  if (expectedStageDir) {
    if (path.resolve(error.stageDir) !== path.resolve(expectedStageDir)) {
      fail(`${context}: stageDir should point at the kept adapter stage, got ${error.stageDir}`);
    }
  } else {
    if (!error.adapterOutputPath) {
      fail(`${context}: adapterOutputPath should be reported with stageDir`);
    }
    if (path.resolve(error.stageDir) !== path.dirname(path.resolve(error.adapterOutputPath))) {
      fail(`${context}: stageDir should be the adapter output directory`);
    }
  }
  if (shouldExist && !fs.existsSync(error.stageDir)) {
    fail(`${context}: stageDir should exist on disk`);
  }
  assertAdapterScratchDirMetadata(error, context, { expectedStageDir, shouldExist });
}

function assertAdapterScratchDirMetadata(error, context, { expectedStageDir = null, shouldExist = false } = {}) {
  if (!error.scratchDir) {
    fail(`${context}: scratchDir should be reported`);
  }
  const expectedScratchDir = expectedStageDir
    ? path.join(expectedStageDir, "scratch")
    : error.stageDir
      ? path.join(error.stageDir, "scratch")
      : null;
  if (expectedScratchDir && path.resolve(error.scratchDir) !== path.resolve(expectedScratchDir)) {
    fail(`${context}: scratchDir should point at the adapter scratch directory, got ${error.scratchDir}`);
  }
  if (shouldExist && !fs.existsSync(error.scratchDir)) {
    fail(`${context}: scratchDir should exist on disk`);
  }
}

function assertAdapterStreamPathMetadata(error, context, { expectedStageDir = null, shouldExist = false } = {}) {
  const expectations = [
    ["adapterStdoutPath", "reference-adapter.stdout.log"],
    ["adapterStderrPath", "reference-adapter.stderr.log"]
  ];
  for (const [key, fileName] of expectations) {
    if (!error[key]) {
      fail(`${context}: ${key} should be reported`);
    }
    if (path.basename(error[key]) !== fileName) {
      fail(`${context}: ${key} should name ${fileName}, got ${error[key]}`);
    }
    if (expectedStageDir) {
      const expectedPath = path.join(expectedStageDir, fileName);
      if (path.resolve(error[key]) !== path.resolve(expectedPath)) {
        fail(`${context}: ${key} should point at the kept stage stream log, got ${error[key]}`);
      }
    } else {
      if (!error.adapterOutputPath) {
        fail(`${context}: adapterOutputPath should be reported with ${key}`);
      }
      if (path.dirname(path.resolve(error[key])) !== path.dirname(path.resolve(error.adapterOutputPath))) {
        fail(`${context}: ${key} should live beside adapterOutputPath`);
      }
    }
    if (shouldExist && !fs.existsSync(error[key])) {
      fail(`${context}: ${key} should exist on disk`);
    }
  }
}

function referencePointCloudPointCount(reference) {
  const chunksById = new Map((reference?.chunks || []).map((chunk) => [chunk?.id, chunk]));
  let pointCount = 0;
  for (const object of Object.values(reference?.objects || {})) {
    if (object?.kind !== "point-cloud") continue;
    if (Array.isArray(object.points)) pointCount += object.points.length;
    for (const chunkId of object.chunkIds || []) {
      const chunk = chunksById.get(chunkId);
      if (Number.isInteger(chunk?.pointCount)) pointCount += chunk.pointCount;
    }
  }
  return pointCount;
}

function referencePrimitiveCounts(reference) {
  const counts = {
    referenceLineSegmentCount: 0,
    referenceMeshFaceCount: 0
  };
  for (const object of Object.values(reference?.objects || {})) {
    if (object?.kind === "line-set" && Array.isArray(object.lineSegments)) {
      counts.referenceLineSegmentCount += object.lineSegments.length;
    } else if (object?.kind === "mesh" && Array.isArray(object.faces)) {
      counts.referenceMeshFaceCount += object.faces.length;
    }
  }
  return counts;
}

function referenceObjectKindCounts(reference) {
  return Object.fromEntries(Object.values(reference?.objects || {}).reduce((counts, object) => {
    const kind = object?.kind || "unknown";
    counts.set(kind, (counts.get(kind) || 0) + 1);
    return counts;
  }, new Map()));
}

function referenceObjectSummaryEntry(object = {}, chunksById = new Map()) {
  const chunkIds = Array.isArray(object?.chunkIds)
    ? object.chunkIds.filter((chunkId) => typeof chunkId === "string" && chunkId)
    : [];
  const chunkPointCount = chunkIds.reduce((total, chunkId) => {
    const chunk = chunksById.get(chunkId);
    return total + (Number.isInteger(chunk?.pointCount) ? chunk.pointCount : 0);
  }, 0);
  const inlinePointCount = Array.isArray(object?.points) ? object.points.length : null;
  const pointCount = object?.kind === "point-cloud"
    ? (inlinePointCount || 0) + chunkPointCount
    : null;
  return {
    id: typeof object?.id === "string" ? object.id : null,
    kind: typeof object?.kind === "string" ? object.kind : null,
    name: typeof object?.name === "string" ? object.name : null,
    layer: typeof object?.layer === "string" ? object.layer : null,
    boundsMin: Array.isArray(object?.bounds?.min) ? object.bounds.min : null,
    boundsMax: Array.isArray(object?.bounds?.max) ? object.bounds.max : null,
    vertexCount: Array.isArray(object?.vertices) ? object.vertices.length : null,
    lineSegmentCount: Array.isArray(object?.lineSegments) ? object.lineSegments.length : null,
    faceCount: Array.isArray(object?.faces) ? object.faces.length : null,
    inlinePointCount,
    chunkCount: chunkIds.length,
    chunkPointCount,
    pointCount
  };
}

function referenceLayerObjectCounts(objects) {
  const counts = new Map();
  for (const object of Object.values(objects || {})) {
    if (typeof object?.layer !== "string" || !object.layer) continue;
    counts.set(object.layer, (counts.get(object.layer) || 0) + 1);
  }
  return counts;
}

function referenceLayerSummaryEntry(layer = {}, objectCounts = new Map()) {
  const display = layer?.display && typeof layer.display === "object" ? layer.display : null;
  const id = typeof layer?.id === "string" ? layer.id : null;
  return {
    id,
    name: typeof layer?.name === "string" ? layer.name : null,
    objectCount: id ? objectCounts.get(id) || 0 : 0,
    displayVisible: typeof display?.visible === "boolean" ? display.visible : null,
    displayColor: typeof display?.color === "string" ? display.color : null,
    displayEdgeColor: typeof display?.edgeColor === "string" ? display.edgeColor : null,
    displayOpacity: Number.isFinite(display?.opacity) ? display.opacity : null,
    displayPointSize: Number.isFinite(display?.pointSize) ? display.pointSize : null
  };
}

function assertSummaryReferenceAssetMetadata(summary, reference, context) {
  const bounds = reference?.asset?.bounds || {};
  const coordinateSystem = reference?.asset?.coordinateSystem || null;
  if (summary.referenceUnits !== (reference?.asset?.units || null)) {
    fail(`${context}: referenceUnits should match canonical asset.units, got ${summary.referenceUnits}`);
  }
  if (JSON.stringify(summary.referenceBoundsMin) !== JSON.stringify(bounds.min || null)) {
    fail(`${context}: referenceBoundsMin should match canonical asset.bounds.min`);
  }
  if (JSON.stringify(summary.referenceBoundsMax) !== JSON.stringify(bounds.max || null)) {
    fail(`${context}: referenceBoundsMax should match canonical asset.bounds.max`);
  }
  if (JSON.stringify(summary.referenceCoordinateSystem) !== JSON.stringify(coordinateSystem)) {
    fail(`${context}: referenceCoordinateSystem should match canonical asset.coordinateSystem`);
  }
  if (JSON.stringify(summary.referenceCoordinateSystemOrigin) !== JSON.stringify(coordinateSystem?.origin || null)) {
    fail(`${context}: referenceCoordinateSystemOrigin should match canonical asset.coordinateSystem.origin`);
  }
  if (JSON.stringify(summary.referenceCoordinateSystemAxisX) !== JSON.stringify(coordinateSystem?.axisX || null)) {
    fail(`${context}: referenceCoordinateSystemAxisX should match canonical asset.coordinateSystem.axisX`);
  }
  if (JSON.stringify(summary.referenceCoordinateSystemAxisY) !== JSON.stringify(coordinateSystem?.axisY || null)) {
    fail(`${context}: referenceCoordinateSystemAxisY should match canonical asset.coordinateSystem.axisY`);
  }
  if (JSON.stringify(summary.referenceCoordinateSystemAxisZ) !== JSON.stringify(coordinateSystem?.axisZ || null)) {
    fail(`${context}: referenceCoordinateSystemAxisZ should match canonical asset.coordinateSystem.axisZ`);
  }
}

function assertSummaryReferenceSchemaMetadata(summary, reference, context) {
  const schema = reference?.schema || null;
  const schemaVersion = reference?.schemaVersion || null;
  if (summary.referenceSchema !== schema) {
    fail(`${context}: referenceSchema should be ${schema}, got ${summary.referenceSchema}`);
  }
  if (summary.referenceSchemaVersion !== schemaVersion) {
    fail(`${context}: referenceSchemaVersion should be ${schemaVersion}, got ${summary.referenceSchemaVersion}`);
  }
  if (summary.schema !== schema || summary.schemaVersion !== schemaVersion) {
    fail(`${context}: legacy schema/schemaVersion should match canonical reference schema metadata`);
  }
}

function assertSummaryReferenceStructure(summary, reference, context) {
  const objects = reference?.objects || {};
  const layers = reference?.layers || {};
  const chunks = Array.isArray(reference?.chunks) ? reference.chunks : [];
  const objectIds = Object.keys(objects);
  const layerIds = Object.keys(layers);
  const chunkIds = chunks.map((chunk) => chunk?.id).filter((id) => typeof id === "string" && id);
  const objectCount = objectIds.length;
  const layerCount = layerIds.length;
  const chunkCount = chunkIds.length;
  const objectKindCounts = referenceObjectKindCounts(reference);
  const chunksById = new Map(chunks.map((chunk) => [chunk?.id, chunk]));
  const layerObjectCounts = referenceLayerObjectCounts(objects);
  const expectedObjectEntries = Object.values(objects)
    .map((object) => referenceObjectSummaryEntry(object, chunksById))
    .slice(0, REFERENCE_STRUCTURE_ENTRY_LIMIT);
  const expectedLayerEntries = Object.values(layers)
    .map((layer) => referenceLayerSummaryEntry(layer, layerObjectCounts))
    .slice(0, REFERENCE_STRUCTURE_ENTRY_LIMIT);
  if (summary.referenceObjectCount !== objectCount) {
    fail(`${context}: referenceObjectCount should be ${objectCount}, got ${summary.referenceObjectCount}`);
  }
  if (summary.referenceLayerCount !== layerCount) {
    fail(`${context}: referenceLayerCount should be ${layerCount}, got ${summary.referenceLayerCount}`);
  }
  if (summary.referenceChunkCount !== chunkCount) {
    fail(`${context}: referenceChunkCount should be ${chunkCount}, got ${summary.referenceChunkCount}`);
  }
  if (summary.objectCount !== objectCount || summary.layerCount !== layerCount || summary.chunkCount !== chunkCount) {
    fail(`${context}: legacy object/layer/chunk counts should match canonical reference structure`);
  }
  if (JSON.stringify(summary.referenceObjectIds) !== JSON.stringify(objectIds.slice(0, REFERENCE_STRUCTURE_ENTRY_LIMIT))) {
    fail(`${context}: referenceObjectIds should expose bounded object ids, got ${JSON.stringify(summary.referenceObjectIds)}`);
  }
  if (summary.referenceObjectIdOmittedCount !== Math.max(0, objectIds.length - REFERENCE_STRUCTURE_ENTRY_LIMIT)) {
    fail(`${context}: referenceObjectIdOmittedCount should match omitted object ids, got ${summary.referenceObjectIdOmittedCount}`);
  }
  if (JSON.stringify(summary.referenceLayerIds) !== JSON.stringify(layerIds.slice(0, REFERENCE_STRUCTURE_ENTRY_LIMIT))) {
    fail(`${context}: referenceLayerIds should expose bounded layer ids, got ${JSON.stringify(summary.referenceLayerIds)}`);
  }
  if (summary.referenceLayerIdOmittedCount !== Math.max(0, layerIds.length - REFERENCE_STRUCTURE_ENTRY_LIMIT)) {
    fail(`${context}: referenceLayerIdOmittedCount should match omitted layer ids, got ${summary.referenceLayerIdOmittedCount}`);
  }
  if (JSON.stringify(summary.referenceChunkIds) !== JSON.stringify(chunkIds.slice(0, REFERENCE_STRUCTURE_ENTRY_LIMIT))) {
    fail(`${context}: referenceChunkIds should expose bounded chunk ids, got ${JSON.stringify(summary.referenceChunkIds)}`);
  }
  if (summary.referenceChunkIdOmittedCount !== Math.max(0, chunkIds.length - REFERENCE_STRUCTURE_ENTRY_LIMIT)) {
    fail(`${context}: referenceChunkIdOmittedCount should match omitted chunk ids, got ${summary.referenceChunkIdOmittedCount}`);
  }
  if (JSON.stringify(summary.referenceObjectEntries) !== JSON.stringify(expectedObjectEntries)) {
    fail(`${context}: referenceObjectEntries should expose bounded object summaries, got ${JSON.stringify(summary.referenceObjectEntries)}`);
  }
  if (summary.referenceObjectEntryOmittedCount !== Math.max(0, objectIds.length - REFERENCE_STRUCTURE_ENTRY_LIMIT)) {
    fail(`${context}: referenceObjectEntryOmittedCount should match omitted object summaries, got ${summary.referenceObjectEntryOmittedCount}`);
  }
  if (JSON.stringify(summary.referenceLayerEntries) !== JSON.stringify(expectedLayerEntries)) {
    fail(`${context}: referenceLayerEntries should expose bounded layer summaries, got ${JSON.stringify(summary.referenceLayerEntries)}`);
  }
  if (summary.referenceLayerEntryOmittedCount !== Math.max(0, layerIds.length - REFERENCE_STRUCTURE_ENTRY_LIMIT)) {
    fail(`${context}: referenceLayerEntryOmittedCount should match omitted layer summaries, got ${summary.referenceLayerEntryOmittedCount}`);
  }
  for (const [kind, count] of Object.entries(objectKindCounts)) {
    if (summary.referenceObjectKindCounts?.[kind] !== count) {
      fail(`${context}: referenceObjectKindCounts.${kind} should be ${count}`);
    }
    if (summary.objectKindCounts?.[kind] !== count) {
      fail(`${context}: objectKindCounts.${kind} should be ${count}`);
    }
  }
}

function incrementAggregateCount(counts, key) {
  if (typeof key !== "string" || !key) return;
  counts[key] = (counts[key] || 0) + 1;
}

function addAggregateFinite(aggregate, key, value) {
  if (!Number.isFinite(value)) return;
  aggregate[key] += value;
}

function expectedCheckReferencesAggregate(result) {
  const aggregate = {
    selectedAssetCount: Object.keys(result.assets || {}).length,
    readyAssetCount: result.referenceReadyCount || 0,
    needsAttentionAssetCount: result.referenceNeedsAttentionCount || 0,
    canonicalManifestCount: 0,
    readyCanonicalManifestCount: 0,
    objectCount: 0,
    layerCount: 0,
    chunkCount: 0,
    lineSegmentCount: 0,
    meshFaceCount: 0,
    pointCloudPointCount: 0,
    chunkFileCount: 0,
    chunkFileSizeBytes: 0,
    chunkFileMissingCount: 0,
    chunkFileInvalidCount: 0,
    chunkPointCount: 0,
    diagnosticCount: 0,
    auditStatusCounts: { ...(result.referenceAuditStatusCounts || {}) },
    auditSeverityCounts: { ...(result.referenceAuditSeverityCounts || {}) },
    sourceFormatCounts: {},
    sourceAdapterCounts: {},
    objectKindCounts: {}
  };
  for (const summary of Object.values(result.assets || {})) {
    if (summary?.referenceSchema !== "bobercad-reference-geometry" || summary.referenceSchemaVersion !== "0.1.0") continue;
    aggregate.canonicalManifestCount += 1;
    if (summary.referenceReady) aggregate.readyCanonicalManifestCount += 1;
    addAggregateFinite(aggregate, "objectCount", summary.referenceObjectCount);
    addAggregateFinite(aggregate, "layerCount", summary.referenceLayerCount);
    addAggregateFinite(aggregate, "chunkCount", summary.referenceChunkCount);
    addAggregateFinite(aggregate, "lineSegmentCount", summary.referenceLineSegmentCount);
    addAggregateFinite(aggregate, "meshFaceCount", summary.referenceMeshFaceCount);
    addAggregateFinite(aggregate, "pointCloudPointCount", summary.referencePointCloudPointCount);
    addAggregateFinite(aggregate, "chunkFileCount", summary.referenceChunkFileCount);
    addAggregateFinite(aggregate, "chunkFileSizeBytes", summary.referenceChunkFileSizeBytes);
    addAggregateFinite(aggregate, "chunkFileMissingCount", summary.referenceChunkFileMissingCount);
    addAggregateFinite(aggregate, "chunkFileInvalidCount", summary.referenceChunkFileInvalidCount);
    addAggregateFinite(aggregate, "chunkPointCount", summary.referenceChunkPointCount);
    addAggregateFinite(aggregate, "diagnosticCount", summary.diagnosticCount);
    incrementAggregateCount(aggregate.sourceFormatCounts, summary.sourceFormat);
    incrementAggregateCount(aggregate.sourceAdapterCounts, summary.sourceAdapter || "built-in-or-none");
    for (const [kind, count] of Object.entries(summary.referenceObjectKindCounts || {})) {
      if (Number.isFinite(count)) aggregate.objectKindCounts[kind] = (aggregate.objectKindCounts[kind] || 0) + count;
    }
  }
  return aggregate;
}

function assertCheckReferencesAggregate(result, context) {
  const expected = expectedCheckReferencesAggregate(result);
  if (JSON.stringify(result.referenceAggregate) !== JSON.stringify(expected)) {
    fail(`${context}: referenceAggregate should summarize selected reference assets, got ${JSON.stringify(result.referenceAggregate)}, expected ${JSON.stringify(expected)}`);
  }
  if (result.referenceAuditContractVersion !== REFERENCE_AUDIT_CONTRACT_VERSION) {
    fail(`${context}: referenceAuditContractVersion should be ${REFERENCE_AUDIT_CONTRACT_VERSION}, got ${result.referenceAuditContractVersion}`);
  }
  assertCheckReferencesProjectFileMetadata(result, context);
  assertCheckReferencesAuditLimits(result, context);
  assertCheckReferencesAuditStatusDefinitions(result, context);
  assertCheckReferencesAuditSeverityCounts(result, context);
  assertCheckReferencesAssetEntries(result, context);
  assertCheckReferencesNeedsAttentionEntries(result, context);
  assertCheckReferencesErrorSummary(result, context);
  assertCheckReferencesAuditFingerprint(result, context);
  assertCheckReferencesAuditDecision(result, context);
}

function assertCheckReferencesProjectFileMetadata(result, context) {
  if (result.projectFileName !== path.basename(result.projectPath || "")) {
    fail(`${context}: projectFileName should match project basename, got ${result.projectFileName}`);
  }
  if (!result.projectPath || !fs.existsSync(result.projectPath) || !fs.statSync(result.projectPath).isFile()) {
    if (result.projectFileSizeBytes !== null || result.projectFileModifiedTime !== null || result.projectStatFingerprint !== null) {
      fail(`${context}: missing or non-file project should report null project stat metadata`);
    }
    return;
  }
  const stat = fs.statSync(result.projectPath);
  if (result.projectFileSizeBytes !== stat.size) {
    fail(`${context}: projectFileSizeBytes should match project stat size, got ${result.projectFileSizeBytes}`);
  }
  if (result.projectFileModifiedTime !== stat.mtime.toISOString()) {
    fail(`${context}: projectFileModifiedTime should match project stat mtime, got ${result.projectFileModifiedTime}`);
  }
  if (result.projectStatFingerprint !== expectedSourceStatFingerprint(result.projectPath)) {
    fail(`${context}: projectStatFingerprint should match project stat fingerprint, got ${result.projectStatFingerprint}`);
  }
}

