function expectedReferenceAuditSeverityCounts(result) {
  const counts = {};
  for (const summary of Object.values(result.assets || {})) {
    const severity = expectedReferenceAuditSeverity(summary?.referenceAuditStatus);
    counts[severity] = (counts[severity] || 0) + 1;
  }
  if (
    result.requestedAssetId
    && result.referenceAssetCount === 0
    && (result.errors || []).some((error) => String(error || "").includes(`referenceGeometry.assets.${result.requestedAssetId} does not exist`))
  ) {
    const severity = expectedReferenceAuditSeverity("missing-asset");
    counts[severity] = (counts[severity] || 0) + 1;
  }
  return counts;
}

