function assertCheckReferencesNeedsAttentionEntries(result, context) {
  const entries = Object.entries(result.assets || {})
    .filter(([, summary]) => summary?.referenceReady !== true)
    .sort(([leftAssetId, leftSummary], [rightAssetId, rightSummary]) => {
      const rankDelta = (rightSummary?.referenceAuditStatusRank ?? -1) - (leftSummary?.referenceAuditStatusRank ?? -1);
      if (rankDelta) return rankDelta;
      return leftAssetId.localeCompare(rightAssetId);
    })
    .map(([assetId, summary]) => expectedCheckReferencesNeedsAttentionEntry(assetId, summary));
  const expectedEntries = entries.slice(0, REFERENCE_NEEDS_ATTENTION_ENTRY_LIMIT);
  if (JSON.stringify(result.referenceNeedsAttentionEntries) !== JSON.stringify(expectedEntries)) {
    fail(`${context}: referenceNeedsAttentionEntries should expose bounded non-ready reference assets, got ${JSON.stringify(result.referenceNeedsAttentionEntries)}, expected ${JSON.stringify(expectedEntries)}`);
  }
  if (result.referenceNeedsAttentionEntryOmittedCount !== Math.max(0, entries.length - expectedEntries.length)) {
    fail(`${context}: referenceNeedsAttentionEntryOmittedCount should match omitted non-ready reference assets, got ${result.referenceNeedsAttentionEntryOmittedCount}`);
  }
}

function boundedCheckReferencesErrorText(error) {
  const text = typeof error === "string" ? error : String(error ?? "");
  return text.length > 320 ? `${text.slice(0, 320)}...` : text;
}

