  const errors = Array.isArray(result.errors) ? result.errors : [];
  return errors
    .slice(0, REFERENCE_AUDIT_TOP_LEVEL_ERROR_ENTRY_LIMIT)
    .map(boundedCheckReferencesErrorText);
